import type { Metadata } from "next";

import { contact, locations, site } from "@/content/site";
import { accreditations } from "@/content/accreditations";

/**
 * The card generated by `app/opengraph-image.tsx`.
 *
 * Next's file convention only covers the segment the file sits in — it does not
 * cascade to nested routes — so interior pages have to name the route
 * explicitly or ship with no card at all. Verified against the built HTML.
 */
const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.name} — ${site.tagline}`,
};

/**
 * Builds page metadata from a title/description pair, filling in the canonical
 * URL, Open Graph and Twitter cards so no page can ship without them.
 */
export function pageMetadata({
  title,
  description,
  path,
  keywords,
  type = "website",
  publishedTime,
}: {
  title: string;
  description: string;
  path: string;
  keywords?: string[];
  type?: "website" | "article";
  publishedTime?: string;
}): Metadata {
  const url = `${site.url}${path}`;

  return {
    title,
    description,
    keywords,
    alternates: { canonical: url },
    openGraph: {
      type,
      url,
      title,
      description,
      siteName: site.name,
      locale: site.locale,
      images: [OG_IMAGE],
      ...(publishedTime ? { publishedTime } : {}),
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [OG_IMAGE.url],
    },
  };
}

/** Organisation-level structured data, emitted once from the root layout. */
export function organisationJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": ["Organization", "ResearchOrganization"],
    "@id": `${site.url}/#organisation`,
    name: site.name,
    legalName: site.legalName,
    url: site.url,
    logo: `${site.url}/brand/nsrl-logo.png`,
    description: site.shortDescription,
    slogan: site.tagline,
    /* No `sameAs`. It listed a LinkedIn company page that is not ours;
       an Organization claiming a profile it does not own is worse than
       claiming none. Restore it when a verified profile exists. */
    telephone: contact.phoneDisplay,
    email: contact.email,
    address: locations.map((location) => ({
      "@type": "PostalAddress",
      name: location.label,
      streetAddress: location.street,
      addressLocality: location.locality,
      addressRegion: location.region,
      postalCode: location.postalCode,
      addressCountry: "IN",
    })),
    hasCredential: accreditations.map((accreditation) => ({
      "@type": "EducationalOccupationalCredential",
      name: accreditation.name,
      credentialCategory: accreditation.abbr,
      recognizedBy: { "@type": "Organization", name: accreditation.issuer },
    })),
    contactPoint: [
      {
        "@type": "ContactPoint",
        contactType: "sales",
        telephone: contact.phoneDisplay,
        email: contact.email,
        areaServed: "Worldwide",
        availableLanguage: ["en"],
      },
    ],
  };
}

/** Website node, so search engines can attach a sitelinks search box later. */
export function websiteJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": `${site.url}/#website`,
    url: site.url,
    name: site.name,
    publisher: { "@id": `${site.url}/#organisation` },
    inLanguage: "en-IN",
  };
}

/** Service node for a scientific division or industry programme. */
export function serviceJsonLd({
  name,
  description,
  path,
  serviceType,
}: {
  name: string;
  description: string;
  path: string;
  serviceType: string;
}) {
  return {
    "@context": "https://schema.org",
    "@type": "Service",
    name,
    description,
    serviceType,
    url: `${site.url}${path}`,
    provider: { "@id": `${site.url}/#organisation` },
    areaServed: "Worldwide",
  };
}

/** Renders a JSON-LD block. Kept here so pages never hand-roll the script tag. */
export function JsonLd({ data }: { data: object }) {
  return (
    <script
      type="application/ld+json"
      dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }}
    />
  );
}
